    """Compute max clustered SE across 3 judge positions.

    Returns dict with coefficients, max SEs, t-stats, and p-values.
    """
    fit_ols = sm.OLS(y, X_with_const).fit()

    max_se = np.zeros(3)  # intercept, log_keff, log_eta

